// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title LandTransferContract — Rongai Blockchain Land Registry
/// @notice Manages land ownership transfers with officer approval workflow.
///         Landholders initiate transfers; Registry Officers approve or reject.
///         Ownership is verified on-chain against LandRegistry before transfer.

/// @dev Minimal interface to verify parcel ownership from LandRegistry
interface ILandRegistry {
    struct RegistryEntry {
        string  parcelId;
        string  titleDeedNumber;
        string  lrNumber;
        address currentOwner;
        string  ownerDID;
        string  landUse;
        uint256 areaSquareMeters;
        uint256 landValueKES;
        bool    isActive;
        uint256 registeredAt;
        uint256 lastUpdatedAt;
    }
    function getParcel(string memory parcelId) external view returns (RegistryEntry memory);
    function isParcelRegistered(string memory parcelId) external view returns (bool);
}

contract LandTransferContract is Ownable, ReentrancyGuard {

    // ── Transfer Status ───────────────────────────────────────────
    enum Status { Pending, UnderReview, Approved, Rejected, Completed }

    // ── Transfer Record ───────────────────────────────────────────
    struct TransferRecord {
        string  transferId;
        string  parcelId;
        address seller;
        address buyer;
        string  sellerDID;
        string  buyerDID;
        uint256 agreedPriceKES;
        string  transferType;
        string  ipfsDocHash;
        Status  status;
        uint256 requestTimestamp;
        uint256 actionTimestamp;
        address actionedBy;
        bool    exists;
    }

    // ── Officer Registry ──────────────────────────────────────────
    mapping(address => bool) private _officers;
    address[] private _officerList;

    // ── LandRegistry reference ────────────────────────────────────
    address private _landRegistryAddress;

    // ── Storage ───────────────────────────────────────────────────
    mapping(string  => TransferRecord) private _transfers;
    mapping(string  => string[])       private _parcelTxns;
    mapping(address => string[])       private _sellerTxns;
    mapping(address => string[])       private _buyerTxns;
    string[]  private _allTransferIds;
    uint256   private _totalTransfers;

    // ── Events ────────────────────────────────────────────────────
    event TransferInitiated(
        string  indexed transferId,
        string  indexed parcelId,
        address indexed seller,
        address buyer,
        uint256 agreedPriceKES,
        string  transferType
    );
    event TransferStatusUpdated(string indexed transferId, Status newStatus, address actionedBy);
    event OfficerAdded(address indexed officer);
    event OfficerRemoved(address indexed officer);
    event LandRegistrySet(address indexed registryAddress);

    // ── Modifiers ─────────────────────────────────────────────────
    modifier onlyOfficer() {
        require(
            _officers[msg.sender] || msg.sender == owner(),
            "LandTransfer: caller is not a Registry Officer"
        );
        _;
    }

    modifier transferMustExist(string memory transferId) {
        require(_transfers[transferId].exists, "Transfer not found");
        _;
    }

    // ── Constructor ───────────────────────────────────────────────
    constructor() Ownable(msg.sender) {
        _officers[msg.sender] = true;
        _officerList.push(msg.sender);
        emit OfficerAdded(msg.sender);
    }

    // ── Link LandRegistry (Owner only) ───────────────────────────
    /// @notice Set the LandRegistry contract address for ownership verification
    function setLandRegistry(address registryAddress) external onlyOwner {
        require(registryAddress != address(0), "Invalid registry address");
        _landRegistryAddress = registryAddress;
        emit LandRegistrySet(registryAddress);
    }

    function getLandRegistryAddress() external view returns (address) {
        return _landRegistryAddress;
    }

    // ── Officer Management ────────────────────────────────────────
    function addOfficer(address officer) external onlyOwner {
        require(officer != address(0), "Invalid officer address");
        require(!_officers[officer],   "Already an officer");
        _officers[officer] = true;
        _officerList.push(officer);
        emit OfficerAdded(officer);
    }

    function removeOfficer(address officer) external onlyOwner {
        require(officer != owner(), "Cannot remove deployer");
        require(_officers[officer], "Not an officer");
        _officers[officer] = false;
        emit OfficerRemoved(officer);
    }

    function isOfficer(address wallet) external view returns (bool) {
        return _officers[wallet];
    }

    function getOfficers() external view returns (address[] memory) {
        return _officerList;
    }

    // ══════════════════════════════════════════════════════════════
    // INITIATE TRANSFER — with 3-layer ownership verification
    // ══════════════════════════════════════════════════════════════
    /// @notice A landholder initiates a transfer of their parcel.
    ///
    ///         Three on-chain checks enforced automatically:
    ///         ① msg.sender must equal the seller address
    ///         ② Parcel must exist and be active in LandRegistry
    ///         ③ Seller must be the current owner in LandRegistry
    function initiateTransfer(
        string  memory transferId,
        string  memory parcelId,
        address seller,
        address buyer,
        string  memory sellerDID,
        string  memory buyerDID,
        uint256 agreedPriceKES,
        string  memory transferType,
        string  memory ipfsDocHash
    ) external nonReentrant {

        // ── Basic validations ──────────────────────────────────────
        require(!_transfers[transferId].exists, "Transfer ID already exists");
        require(bytes(transferId).length  > 0,  "Transfer ID cannot be empty");
        require(bytes(parcelId).length    > 0,  "Parcel ID cannot be empty");
        require(buyer  != address(0),           "Invalid buyer address");
        require(seller != buyer,                "Seller and buyer cannot be the same");

        // ── Check ①: Caller must be the seller ────────────────────
        require(
            msg.sender == seller,
            "Only the seller can initiate their own transfer"
        );

        // ── Checks ② & ③: Verify ownership in LandRegistry ───────
        if (_landRegistryAddress != address(0)) {
            ILandRegistry registry = ILandRegistry(_landRegistryAddress);

            require(
                registry.isParcelRegistered(parcelId),
                "Parcel not found in Land Registry. Register the parcel before initiating a transfer."
            );

            ILandRegistry.RegistryEntry memory entry = registry.getParcel(parcelId);

            require(
                entry.isActive,
                "Parcel is not active in the Land Registry."
            );

            require(
                entry.currentOwner == seller,
                "Ownership verification failed: your wallet is not the registered owner of this parcel."
            );
        }

        // ── Store the transfer record ──────────────────────────────
        _transfers[transferId] = TransferRecord({
            transferId:       transferId,
            parcelId:         parcelId,
            seller:           seller,
            buyer:            buyer,
            sellerDID:        sellerDID,
            buyerDID:         buyerDID,
            agreedPriceKES:   agreedPriceKES,
            transferType:     transferType,
            ipfsDocHash:      ipfsDocHash,
            status:           Status.Pending,
            requestTimestamp: block.timestamp,
            actionTimestamp:  0,
            actionedBy:       address(0),
            exists:           true
        });

        _parcelTxns[parcelId].push(transferId);
        _sellerTxns[seller].push(transferId);
        _buyerTxns[buyer].push(transferId);
        _allTransferIds.push(transferId);
        _totalTransfers++;

        emit TransferInitiated(
            transferId, parcelId, seller, buyer, agreedPriceKES, transferType
        );
    }

    // ── Officer Actions ───────────────────────────────────────────

    function setUnderReview(string memory transferId)
        external onlyOfficer transferMustExist(transferId)
    {
        require(
            _transfers[transferId].status == Status.Pending,
            "Transfer must be Pending to set Under Review"
        );
        _transfers[transferId].status         = Status.UnderReview;
        _transfers[transferId].actionTimestamp = block.timestamp;
        _transfers[transferId].actionedBy      = msg.sender;
        emit TransferStatusUpdated(transferId, Status.UnderReview, msg.sender);
    }

    function approveTransfer(string memory transferId)
        external onlyOfficer transferMustExist(transferId) nonReentrant
    {
        Status current = _transfers[transferId].status;
        require(
            current == Status.Pending || current == Status.UnderReview,
            "Transfer must be Pending or Under Review to approve"
        );
        _transfers[transferId].status         = Status.Completed;
        _transfers[transferId].actionTimestamp = block.timestamp;
        _transfers[transferId].actionedBy      = msg.sender;
        emit TransferStatusUpdated(transferId, Status.Completed, msg.sender);
    }

    function rejectTransfer(string memory transferId)
        external onlyOfficer transferMustExist(transferId)
    {
        Status current = _transfers[transferId].status;
        require(
            current == Status.Pending || current == Status.UnderReview,
            "Transfer must be Pending or Under Review to reject"
        );
        _transfers[transferId].status         = Status.Rejected;
        _transfers[transferId].actionTimestamp = block.timestamp;
        _transfers[transferId].actionedBy      = msg.sender;
        emit TransferStatusUpdated(transferId, Status.Rejected, msg.sender);
    }

    // ── View Functions ────────────────────────────────────────────
    function getTransfer(string memory transferId)
        external view returns (TransferRecord memory)
    {
        require(_transfers[transferId].exists, "Transfer not found");
        return _transfers[transferId];
    }

    function getTransfersByParcel(string memory parcelId)
        external view returns (string[] memory)
    {
        return _parcelTxns[parcelId];
    }

    function getTransfersBySeller(address seller)
        external view returns (string[] memory)
    {
        return _sellerTxns[seller];
    }

    function getTransfersByBuyer(address buyer)
        external view returns (string[] memory)
    {
        return _buyerTxns[buyer];
    }

    function totalTransfers() external view returns (uint256) {
        return _totalTransfers;
    }

    function transferExistsCheck(string memory transferId)
        external view returns (bool)
    {
        return _transfers[transferId].exists;
    }
}

contracts/core/StampDutyPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title StampDutyPayment — Rongai Blockchain Land Registry
/// @notice Handles stamp duty calculation, escrow and KRA remittance
/// @dev Implements Kenya Stamp Duty Act rates: 2% urban / 4% rural

contract StampDutyPayment is Ownable, ReentrancyGuard {

    // ── Payment Status Enum ────────────────────────────────
    enum PaymentStatus {
        Pending,
        Processing,
        Confirmed,
        Failed,
        Refunded
    }

    // ── Payment Record ─────────────────────────────────────
    struct PaymentRecord {
        string        paymentId;             // e.g. "SDP-RNG-2026-00089"
        string        transferId;            // Linked transfer ID
        string        parcelId;              // Land parcel ID
        address       payer;                 // Buyer address
        uint256       transactionValueKES;   // Sale price in KES
        uint256       stampDutyRatePercent;  // 2 or 4
        uint256       stampDutyAmountKES;    // Calculated duty
        uint256       registrationFeeKES;    // Fixed registration fee
        uint256       totalFeesKES;          // Total amount due
        string        paymentMethod;         // M-Pesa / Bank / Escrow
        string        paymentReference;      // M-Pesa ref or bank ref
        string        kraConfirmationCode;   // KRA iTax confirmation
        PaymentStatus status;                // Current status
        uint256       createdAt;             // Record creation time
        uint256       confirmedAt;           // Payment confirmation time
    }

    // ── Constants (Kenya Land Act rates) ──────────────────
    uint256 public constant URBAN_RATE_PERCENT   = 2;   // 2% for urban land
    uint256 public constant RURAL_RATE_PERCENT   = 4;   // 4% for rural land
    uint256 public constant URBAN_THRESHOLD_KES  = 4_000_000; // KES 4M threshold
    uint256 public constant REGISTRATION_FEE_KES = 5_000;     // Fixed KES 5,000

    // ── Storage ────────────────────────────────────────────
    mapping(string => PaymentRecord) private _payments;     // paymentId → record
    mapping(string => bool)          private _paymentExists; // paymentId → exists
    mapping(string => string)        private _transferPayment; // transferId → paymentId

    string[] private _allPaymentIds;

    // ── Events ─────────────────────────────────────────────
    event PaymentCreated(string indexed paymentId, string indexed transferId, uint256 totalFeesKES);
    event PaymentConfirmed(string indexed paymentId, string kraConfirmationCode);
    event PaymentRefunded(string indexed paymentId, address indexed payer);
    event PaymentFailed(string indexed paymentId, string reason);

    // ── Constructor ────────────────────────────────────────
    constructor() Ownable(msg.sender) {}

    // ── Calculate Stamp Duty ───────────────────────────────
    /// @notice Calculates stamp duty based on Kenya land law
    /// @param transactionValueKES  Sale price in Kenya Shillings
    /// @param isUrban              true = urban (2%), false = rural (4%)
    /// @return stampDuty           Stamp duty amount in KES
    /// @return registrationFee     Fixed registration fee in KES
    /// @return totalFees           Total fees payable in KES
    function calculateDuty(uint256 transactionValueKES, bool isUrban)
        public pure
        returns (
            uint256 stampDuty,
            uint256 registrationFee,
            uint256 totalFees
        )
    {
        require(transactionValueKES > 0, "Transaction value must be greater than zero");

        uint256 rate = isUrban ? URBAN_RATE_PERCENT : RURAL_RATE_PERCENT;
        stampDuty       = (transactionValueKES * rate) / 100;
        registrationFee = REGISTRATION_FEE_KES;
        totalFees       = stampDuty + registrationFee;
    }

    // ── Create Payment Record ──────────────────────────────
    /// @notice Creates a new stamp duty payment record
    function createPayment(
        string memory paymentId,
        string memory transferId,
        string memory parcelId,
        address payer,
        uint256 transactionValueKES,
        bool    isUrban,
        string memory paymentMethod
    ) external onlyOwner {
        require(!_paymentExists[paymentId],           "Payment ID already exists");
        require(payer != address(0),                  "Invalid payer address");
        require(transactionValueKES > 0,              "Value must be greater than zero");
        require(
            bytes(_transferPayment[transferId]).length == 0,
            "Payment already exists for this transfer"
        );

        (
            uint256 stampDuty,
            uint256 regFee,
            uint256 totalFees
        ) = calculateDuty(transactionValueKES, isUrban);

        uint256 rate = isUrban ? URBAN_RATE_PERCENT : RURAL_RATE_PERCENT;

        _payments[paymentId] = PaymentRecord({
            paymentId:            paymentId,
            transferId:           transferId,
            parcelId:             parcelId,
            payer:                payer,
            transactionValueKES:  transactionValueKES,
            stampDutyRatePercent: rate,
            stampDutyAmountKES:   stampDuty,
            registrationFeeKES:   regFee,
            totalFeesKES:         totalFees,
            paymentMethod:        paymentMethod,
            paymentReference:     "",
            kraConfirmationCode:  "",
            status:               PaymentStatus.Pending,
            createdAt:            block.timestamp,
            confirmedAt:          0
        });

        _paymentExists[paymentId]      = true;
        _transferPayment[transferId]   = paymentId;
        _allPaymentIds.push(paymentId);

        emit PaymentCreated(paymentId, transferId, totalFees);
    }

    // ── Confirm Payment ────────────────────────────────────
    /// @notice Confirms payment after KRA iTax verification
    function confirmPayment(
        string memory paymentId,
        string memory kraConfirmationCode,
        string memory paymentReference
    ) external onlyOwner {
        require(_paymentExists[paymentId], "Payment not found");
        PaymentRecord storage rec = _payments[paymentId];
        require(
            rec.status == PaymentStatus.Pending ||
            rec.status == PaymentStatus.Processing,
            "Payment cannot be confirmed in current status"
        );

        rec.status              = PaymentStatus.Confirmed;
        rec.kraConfirmationCode = kraConfirmationCode;
        rec.paymentReference    = paymentReference;
        rec.confirmedAt         = block.timestamp;

        emit PaymentConfirmed(paymentId, kraConfirmationCode);
    }

    // ── Mark Payment Failed ────────────────────────────────
    function markPaymentFailed(string memory paymentId, string memory reason)
        external onlyOwner
    {
        require(_paymentExists[paymentId], "Payment not found");
        require(
            _payments[paymentId].status == PaymentStatus.Pending ||
            _payments[paymentId].status == PaymentStatus.Processing,
            "Payment cannot be failed in current status"
        );
        _payments[paymentId].status = PaymentStatus.Failed;
        emit PaymentFailed(paymentId, reason);
    }

    // ── Refund Payment ─────────────────────────────────────
    function refundPayment(string memory paymentId)
        external onlyOwner nonReentrant
    {
        require(_paymentExists[paymentId], "Payment not found");
        PaymentRecord storage rec = _payments[paymentId];
        require(
            rec.status == PaymentStatus.Pending ||
            rec.status == PaymentStatus.Failed,
            "Only pending or failed payments can be refunded"
        );
        rec.status = PaymentStatus.Refunded;
        emit PaymentRefunded(paymentId, rec.payer);
    }

    // ── View Functions ─────────────────────────────────────
    function getPayment(string memory paymentId)
        external view returns (PaymentRecord memory)
    {
        require(_paymentExists[paymentId], "Payment not found");
        return _payments[paymentId];
    }

    function getPaymentByTransfer(string memory transferId)
        external view returns (PaymentRecord memory)
    {
        string memory paymentId = _transferPayment[transferId];
        require(bytes(paymentId).length > 0, "No payment found for this transfer");
        return _payments[paymentId];
    }

    function isPaymentConfirmed(string memory transferId)
        external view returns (bool)
    {
        string memory paymentId = _transferPayment[transferId];
        if (bytes(paymentId).length == 0) return false;
        return _payments[paymentId].status == PaymentStatus.Confirmed;
    }

    function totalPayments() external view returns (uint256) {
        return _allPaymentIds.length;
    }
}

contracts/core/titleDeed.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title TitleDeed — Rongai Blockchain Land Registry
/// @notice Records immutable title deed and transfer certificate hashes on-chain.
///
///         How it works:
///         1. Registry Officer fills in deed details in the browser
///         2. Browser computes keccak256(deedId + parcelId + owner + timestamp)
///         3. Only the hash is sent to the blockchain via issueDeed()
///         4. The printable PDF is generated locally — no personal data stored on-chain
///         5. Anyone can verify a deed by calling verifyDeed(deedId, hash)
///
///         Access model:
///         - owner (deployer)   : add/remove registry officers
///         - registryOfficer    : issue deeds
///         - anyone             : view and verify deeds (read-only)
///
///         Governing law: Land Registration Act, Cap 300 (Kenya)

contract TitleDeed is Ownable {

    // ── Deed Types ────────────────────────────────────────────────
    /// @dev 0 = TitleDeed (initial ownership), 1 = TransferCertificate (after transfer)
    enum DeedType { TitleDeed, TransferCertificate }

    // ── Deed Record ───────────────────────────────────────────────
    struct DeedRecord {
        string   deedId;          // e.g. "DEED-RONGAI-2026-001" — follows county registry format
        string   parcelId;        // Linked parcel ID e.g. "RONGAI/001/2026"
        string   linkedTxId;      // Transfer ID for certificates; "" for initial deeds
        address  owner;           // Owner wallet at time of deed issuance
        bytes32  documentHash;    // keccak256 of deed details computed in browser
        DeedType deedType;        // TitleDeed or TransferCertificate
        uint256  issuedAt;        // Block timestamp of issuance
        address  issuedBy;        // Registry Officer who issued the deed
        bool     exists;          // Duplicate guard
    }

    // ── Officer Registry ──────────────────────────────────────────
    mapping(address => bool) private _officers;
    address[] private _officerList;

    // ── Storage ───────────────────────────────────────────────────
    mapping(string  => DeedRecord) private _deeds;        // deedId   → record
    mapping(string  => string[])   private _parcelDeeds;  // parcelId → deedIds[]
    mapping(address => string[])   private _ownerDeeds;   // owner    → deedIds[]

    string[] private _allDeedIds;

    // ── Events ────────────────────────────────────────────────────
    event DeedIssued(
        string   indexed deedId,
        string   indexed parcelId,
        address  indexed owner,
        bytes32  documentHash,
        DeedType deedType,
        address  issuedBy
    );
    event OfficerAdded(address indexed officer);
    event OfficerRemoved(address indexed officer);

    // ── Modifiers ─────────────────────────────────────────────────
    modifier onlyOfficer() {
        require(
            _officers[msg.sender] || msg.sender == owner(),
            "TitleDeed: caller is not a Registry Officer"
        );
        _;
    }

    // ── Constructor ───────────────────────────────────────────────
    constructor() Ownable(msg.sender) {
        // Deployer is automatically the first officer
        _officers[msg.sender] = true;
        _officerList.push(msg.sender);
        emit OfficerAdded(msg.sender);
    }

    // ══════════════════════════════════════════════════════════════
    // OFFICER MANAGEMENT  (owner only)
    // ══════════════════════════════════════════════════════════════

    /// @notice Whitelist a wallet as a Registry Officer
    /// @param officer Wallet address to grant officer role
    function addOfficer(address officer) external onlyOwner {
        require(officer != address(0), "Invalid officer address");
        require(!_officers[officer],   "Already an officer");
        _officers[officer] = true;
        _officerList.push(officer);
        emit OfficerAdded(officer);
    }

    /// @notice Remove a Registry Officer's access
    /// @param officer Wallet address to revoke
    function removeOfficer(address officer) external onlyOwner {
        require(officer != owner(), "Cannot remove deployer");
        require(_officers[officer], "Not an officer");
        _officers[officer] = false;
        emit OfficerRemoved(officer);
    }

    /// @notice Check if a wallet is a Registry Officer
    function isOfficer(address wallet) external view returns (bool) {
        return _officers[wallet];
    }

    /// @notice Get list of all officers ever added
    function getOfficers() external view returns (address[] memory) {
        return _officerList;
    }

    // ══════════════════════════════════════════════════════════════
    // ISSUE DEED  (officers only)
    // ══════════════════════════════════════════════════════════════

    /// @notice Records a deed hash permanently on-chain.
    ///         The documentHash must be computed in the browser BEFORE calling this.
    ///         Formula: keccak256(abi.encodePacked(deedId, parcelId, owner, timestamp))
    ///
    /// @param deedId       Unique deed identifier following county registry format
    ///                     e.g. "DEED-RONGAI-2026-001"
    /// @param parcelId     Land parcel this deed belongs to e.g. "RONGAI/001/2026"
    /// @param linkedTxId   Transfer ID if this is a TransferCertificate; "" for initial deeds
    /// @param owner        Owner wallet address at time of issuance
    /// @param documentHash keccak256 hash of deed details — computed in browser, never raw data
    /// @param deedType     0 = TitleDeed (initial), 1 = TransferCertificate (after transfer)
    function issueDeed(
        string   memory deedId,
        string   memory parcelId,
        string   memory linkedTxId,
        address  owner,
        bytes32  documentHash,
        DeedType deedType
    ) external onlyOfficer {
        require(bytes(deedId).length   > 0,   "Deed ID cannot be empty");
        require(bytes(parcelId).length > 0,   "Parcel ID cannot be empty");
        require(!_deeds[deedId].exists,        "Deed ID already exists");
        require(owner != address(0),           "Invalid owner address");
        require(documentHash != bytes32(0),    "Invalid document hash");

        // Enforce: TransferCertificate must have a linked transfer ID
        if (deedType == DeedType.TransferCertificate) {
            require(bytes(linkedTxId).length > 0, "Transfer Certificate must have a linked Transfer ID");
        }

        _deeds[deedId] = DeedRecord({
            deedId:       deedId,
            parcelId:     parcelId,
            linkedTxId:   linkedTxId,
            owner:        owner,
            documentHash: documentHash,
            deedType:     deedType,
            issuedAt:     block.timestamp,
            issuedBy:     msg.sender,
            exists:       true
        });

        _parcelDeeds[parcelId].push(deedId);
        _ownerDeeds[owner].push(deedId);
        _allDeedIds.push(deedId);

        emit DeedIssued(deedId, parcelId, owner, documentHash, deedType, msg.sender);
    }

    // ══════════════════════════════════════════════════════════════
    // VERIFY DEED  (public)
    // ══════════════════════════════════════════════════════════════

    /// @notice Verifies a deed by checking its hash matches the on-chain record.
    ///         Use this to prove a printed deed has not been tampered with.
    /// @param deedId       The deed to verify
    /// @param documentHash The hash to check — recompute from deed details to verify
    /// @return true if the hash matches the on-chain record
    function verifyDeed(
        string memory deedId,
        bytes32 documentHash
    ) external view returns (bool) {
        if (!_deeds[deedId].exists) return false;
        return _deeds[deedId].documentHash == documentHash;
    }

    // ══════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS  (public read-only)
    // ══════════════════════════════════════════════════════════════

    /// @notice Get full deed record by deed ID
    function getDeed(string memory deedId)
        external view returns (DeedRecord memory)
    {
        require(_deeds[deedId].exists, "Deed not found");
        return _deeds[deedId];
    }

    /// @notice Get all deed IDs issued for a parcel
    function getDeedsByParcel(string memory parcelId)
        external view returns (string[] memory)
    {
        return _parcelDeeds[parcelId];
    }

    /// @notice Get all deed IDs belonging to an owner wallet
    function getDeedsByOwner(address owner)
        external view returns (string[] memory)
    {
        return _ownerDeeds[owner];
    }

    /// @notice Check if a deed ID exists
    function deedExists(string memory deedId) external view returns (bool) {
        return _deeds[deedId].exists;
    }

    /// @notice Total number of deeds ever issued
    function totalDeeds() external view returns (uint256) {
        return _allDeedIds.length;
    }

    /// @notice Get all deed IDs ever issued (use with caution on large registries)
    function getAllDeedIds() external view returns (string[] memory) {
        return _allDeedIds;
    }
}

